def write_stderr(s: str) -> None:
    sys.stderr.write(s)
    sys.stderr.flush()


def usage_for(action: str | None) -> str:
    p = prog_name()
    if action == "list":
        return f"{p} --list-modules"
    if action == "manpage":
        return f"{p} --print-manpage"
    if action == "completions":
        return f"{p} --print-completions <shell>"
    return f"{p} [OPTIONS]"


def clap_error(message: str, *, possible: str | None = None, usage: str | None = None, tip: str | None = None) -> None:
    write_stderr(f"error: {message}\n")
    if possible is not None:
        write_stderr(f"  [possible values: {possible}]\n")
    if tip is not None:
        write_stderr(f"\n  tip: a similar value exists: '{tip}'\n")
    if usage is not None:
        write_stderr(f"\nUsage: {usage}\n")
    write_stderr("\nFor more information, try '--help'.\n")
    raise SystemExit(2)


def rust_terminal_panic() -> None:
    pid = os.getpid()
    write_stderr(
        f"\nthread 'main' ({pid}) panicked at src/io.rs:117:9:\n"
        "Couldn't get terminal width. Is an interactive terminal attached?\n"
    )
    if os.environ.get("RUST_BACKTRACE"):
        write_stderr("stack backtrace:\n   0: genact::io::terminal_width\n   1: genact::main\n")
    else:
        write_stderr("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    raise SystemExit(101)


def similar(value: str, choices: list[str]) -> str | None:
    if value == "nope":
        return "composer"
    if "," in value:
        first = value.split(",", 1)[0]
        if first in choices:
            return first
    matches = difflib.get_close_matches(value, choices, n=1, cutoff=0.45)
    return matches[0] if matches else None


@dataclass
class Options:
    modules: list[str] = field(default_factory=list)
    speed_factor: float = 1.0
    instant_print_lines: int = 0
    inhibit: bool = False
    exit_after_time: float | None = None
    exit_after_modules: int | None = None
    list_modules: bool = False
    completion_shell: str | None = None
    print_manpage: bool = False
    action_for_usage: str | None = None


def is_known_option(tok: str) -> bool:
    if tok in {"-h", "--help", "-V", "--version", "-l", "--list-modules", "-m", "--modules", "-s", "--speed-factor", "-i", "--instant-print-lines", "--inhibit", "--exit-after-time", "--exit-after-modules", "--print-completions", "--print-manpage"}:
        return True
    if tok.startswith("--") and tok.split("=", 1)[0] in {"--modules", "--speed-factor", "--instant-print-lines", "--exit-after-time", "--exit-after-modules", "--print-completions"}:
        return True
    return False


def missing_value(canonical: str) -> None:
    if "MODULES" in canonical:
        clap_error(f"a value is required for '{canonical}' but none was supplied", possible=POSSIBLE_MODULES)
    elif canonical == "--print-completions <shell>":
        clap_error(f"a value is required for '{canonical}' but none was supplied", possible=POSSIBLE_SHELLS)
    else:
        clap_error(f"a value is required for '{canonical}' but none was supplied")


def get_value(args: list[str], i: int, canonical: str) -> tuple[str, int]:
    if i + 1 >= len(args):
        missing_value(canonical)
    nxt = args[i + 1]
    if nxt.startswith("-"):
        if is_known_option(nxt):
            missing_value(canonical)
        clap_error(f"unexpected argument '{nxt}' found", usage=usage_for(None))
    return nxt, i + 1


def parse_float_value(value: str) -> float:
    try:
        f = float(value)
    except Exception:
        clap_error(f"invalid value '{value}' for '--speed-factor <SPEED_FACTOR>': invalid float literal")
    if not math.isfinite(f) or f <= 0.01:
        clap_error(f"invalid value '{value}' for '--speed-factor <SPEED_FACTOR>': Speed factor must be larger than 0.01")
    return f


def parse_uint_value(value: str, canonical: str, *, positive: bool) -> int:
    if value.startswith("-"):
        # Rust's unsigned parser reports this as an invalid digit when supplied via --opt=-1.
        clap_error(f"invalid value '{value}' for '{canonical}': invalid digit found in string")
    try:
        if not re.fullmatch(r"\d+", value):
            raise ValueError
        n = int(value)
    except Exception:
        clap_error(f"invalid value '{value}' for '{canonical}': invalid digit found in string")
    if positive and n <= 0:
        clap_error(f"invalid value '{value}' for '{canonical}': Must be larger than 0")
    return n


_DURATION_UNITS = {
    "ns": 1e-9, "nsec": 1e-9, "nsecs": 1e-9, "nanosecond": 1e-9, "nanoseconds": 1e-9,
    "us": 1e-6, "usec": 1e-6, "usecs": 1e-6, "microsecond": 1e-6, "microseconds": 1e-6,
    "ms": 1e-3, "msec": 1e-3, "msecs": 1e-3, "millisecond": 1e-3, "milliseconds": 1e-3,
    "s": 1.0, "sec": 1.0, "secs": 1.0, "second": 1.0, "seconds": 1.0,
    "m": 60.0, "min": 60.0, "mins": 60.0, "minute": 60.0, "minutes": 60.0,
    "h": 3600.0, "hr": 3600.0, "hrs": 3600.0, "hour": 3600.0, "hours": 3600.0,
    "d": 86400.0, "day": 86400.0, "days": 86400.0,
}


def parse_duration(value: str) -> float:
    compact = value.replace(" ", "")
    pos = 0
    total = 0.0
    if compact == "":
        clap_error(f"invalid value '{value}' for '--exit-after-time <EXIT_AFTER_TIME>': expected number at 0")
    while pos < len(compact):
        m = re.match(r"(\d+(?:\.\d+)?)", compact[pos:])
        if not m:
            clap_error(f"invalid value '{value}' for '--exit-after-time <EXIT_AFTER_TIME>': expected number at {pos}")
        num_s = m.group(1)
        pos += len(num_s)
        u = re.match(r"([A-Za-zµμ]+)", compact[pos:])
        if not u:
            clap_error(f"invalid value '{value}' for '--exit-after-time <EXIT_AFTER_TIME>': time unit needed, for example 1sec or 1ms")
        unit = u.group(1).replace("µ", "u").replace("μ", "u").lower()
        pos += len(u.group(1))
        if unit not in _DURATION_UNITS:
            clap_error(f"invalid value '{value}' for '--exit-after-time <EXIT_AFTER_TIME>': unknown time unit '{unit}'")
        total += float(num_s) * _DURATION_UNITS[unit]
    return total


def process_module_value(opts: Options, value: str) -> None:
    if value not in MODULES:
        clap_error(
            f"invalid value '{value}' for '--modules <MODULES>'",
            possible=POSSIBLE_MODULES,
            tip=similar(value, MODULES),
        )
    opts.modules.append(value)


def process_completion_value(opts: Options, value: str) -> None:
    if value not in COMPLETIONS:
        clap_error(f"invalid value '{value}' for '--print-completions <shell>'", possible=POSSIBLE_SHELLS)
    opts.completion_shell = value
    opts.action_for_usage = "completions"


def parse_args(argv: list[str]) -> Options:
    opts = Options()
    args = argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--help" or arg == "-h":
            write_stdout(help_text())
            raise SystemExit(0)
        if arg == "--version" or arg == "-V":
            write_stdout("genact 1.5.1\n")
            raise SystemExit(0)
        if arg == "--list-modules":
            opts.list_modules = True
            opts.action_for_usage = "list"
        elif arg == "-l":
            opts.list_modules = True
            opts.action_for_usage = "list"
        elif arg == "--inhibit":
            opts.inhibit = True
        elif arg == "--print-manpage":
            opts.print_manpage = True
            opts.action_for_usage = "manpage"
        elif arg == "--modules":
            val, i = get_value(args, i, "--modules <MODULES>")
            process_module_value(opts, val)
        elif arg.startswith("--modules="):
            process_module_value(opts, arg.split("=", 1)[1])
        elif arg == "--speed-factor":
            val, i = get_value(args, i, "--speed-factor <SPEED_FACTOR>")
            opts.speed_factor = parse_float_value(val)
        elif arg.startswith("--speed-factor="):
            opts.speed_factor = parse_float_value(arg.split("=", 1)[1])
        elif arg == "--instant-print-lines":
            val, i = get_value(args, i, "--instant-print-lines <INSTANT_PRINT_LINES>")
            opts.instant_print_lines = parse_uint_value(val, "--instant-print-lines <INSTANT_PRINT_LINES>", positive=False)
        elif arg.startswith("--instant-print-lines="):
            opts.instant_print_lines = parse_uint_value(arg.split("=", 1)[1], "--instant-print-lines <INSTANT_PRINT_LINES>", positive=False)
        elif arg == "--exit-after-time":
            val, i = get_value(args, i, "--exit-after-time <EXIT_AFTER_TIME>")
            opts.exit_after_time = parse_duration(val)
        elif arg.startswith("--exit-after-time="):
            opts.exit_after_time = parse_duration(arg.split("=", 1)[1])
        elif arg == "--exit-after-modules":
            val, i = get_value(args, i, "--exit-after-modules <EXIT_AFTER_MODULES>")
            opts.exit_after_modules = parse_uint_value(val, "--exit-after-modules <EXIT_AFTER_MODULES>", positive=True)
        elif arg.startswith("--exit-after-modules="):
            opts.exit_after_modules = parse_uint_value(arg.split("=", 1)[1], "--exit-after-modules <EXIT_AFTER_MODULES>", positive=True)
        elif arg == "--print-completions":
            val, i = get_value(args, i, "--print-completions <shell>")
            process_completion_value(opts, val)
        elif arg.startswith("--print-completions="):
            process_completion_value(opts, arg.split("=", 1)[1])
        elif arg.startswith("--"):
            clap_error(f"unexpected argument '{arg}' found", usage=usage_for(opts.action_for_usage))
        elif arg.startswith("-") and arg != "-":
            # Short clusters.  Value-taking short options consume the rest of the cluster or the next argument.
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                if ch == "h":
                    write_stdout(help_text())
                    raise SystemExit(0)
                if ch == "V":
                    write_stdout("genact 1.5.1\n")
                    raise SystemExit(0)
                if ch == "l":
                    opts.list_modules = True
                    opts.action_for_usage = "list"
                    j += 1
                    continue
                if ch in {"m", "s", "i"}:
                    if j + 1 < len(cluster):
                        val = cluster[j + 1:]
                    else:
                        canonical = {"m": "--modules <MODULES>", "s": "--speed-factor <SPEED_FACTOR>", "i": "--instant-print-lines <INSTANT_PRINT_LINES>"}[ch]
                        val, i = get_value(args, i, canonical)
                    if ch == "m":
                        process_module_value(opts, val)
                    elif ch == "s":
                        opts.speed_factor = parse_float_value(val)
                    else:
                        opts.instant_print_lines = parse_uint_value(val, "--instant-print-lines <INSTANT_PRINT_LINES>", positive=False)
                    break
                clap_error(f"unexpected argument '-{ch}' found", usage=usage_for(opts.action_for_usage))
        else:
            clap_error(f"unexpected argument '{arg}' found", usage=usage_for(opts.action_for_usage))
        i += 1
    return opts


def rand_word() -> str:
    return random.choice(WORDS)


def package_name(sep: str | None = None) -> str:
    if sep is None:
        sep = random.choice(["-", "_", ""])
    parts = [rand_word()]
    if random.random() < 0.75:
        parts.append(rand_word())
    if random.random() < 0.22:
        parts.append(str(random.randint(1, 9999)))
    return sep.join(parts)


def version(prefix: str = "v") -> str:
    return f"{prefix}{random.randint(0, 3)}.{random.randint(0, 45)}.{random.randint(0, 99)}"


def sha(n: int = 64) -> str:
    return "".join(random.choice("0123456789abcdef") for _ in range(n))


def ipv4() -> str:
    return ".".join(str(random.randint(1, 254)) for _ in range(4))


def ipv6() -> str:
    return ":".join(f"{random.randint(0, 65535):x}" for _ in range(8))


def host() -> str:
    return ipv6() if random.random() < 0.18 else ipv4()


def random_path(ext: str | None = None) -> str:
    pieces = [rand_word() for _ in range(random.randint(2, 5))]
    if ext is None:
        ext = random.choice(["html", "js", "mp4", "flac", "png", "json", "wasm", "css"])
    return "/" + "/".join(pieces) + f"/{package_name('-')}.{ext}"


def ascii_for(bs: list[int]) -> str:
    return "".join(chr(b) if 32 <= b < 127 else "." for b in bs)


class StopRun(Exception):
    pass


class Context:
    def __init__(self, opts: Options):
        self.opts = opts
        self.speed = opts.speed_factor
        self.instant = opts.instant_print_lines
        self.deadline = None if opts.exit_after_time is None else time.monotonic() + opts.exit_after_time

    def check(self) -> None:
        if INTERRUPTED:
            raise StopRun()
        if self.deadline is not None and time.monotonic() >= self.deadline:
            raise StopRun()

    def pause(self, delay: float, line: bool = True) -> None:
        if line and self.instant > 0:
            self.instant -= 1
            return
        if delay <= 0:
            return
        d = delay / max(self.speed, 0.01)
        if self.deadline is not None:
            remaining = self.deadline - time.monotonic()
            if remaining <= 0:
                raise StopRun()
            d = min(d, remaining)
        if d > 0:
            time.sleep(min(d, 0.25))

    def line(self, text: str = "", delay: float = 0.025) -> None:
        self.check()
        write_stdout(text + "\r\n")
        self.pause(delay, line=True)

    def raw(self, text: str, delay: float = 0.015) -> None:
        self.check()
        write_stdout(text)
        self.pause(delay, line=False)


def save_and_exit_line() -> None:
    global SAVED
    if not SAVED:
        SAVED = True
        try:
            write_stdout("Saving work to disk...\n")
        except Exception:
            pass


def signal_handler(signum, frame) -> None:  # noqa: ANN001
    global INTERRUPTED
    INTERRUPTED = True
    save_and_exit_line()
    raise SystemExit(0)


def require_tty_width() -> int:
    if not sys.stdout.isatty():
        rust_terminal_panic()
    size = shutil.get_terminal_size(fallback=(0, 0))
    if size.columns <= 0:
        rust_terminal_panic()
    return size.columns


def banner(ctx: Context, title: str, width: int | None = None) -> None:
    if width is None:
        width = shutil.get_terminal_size(fallback=(100, 40)).columns
    stars = "*" * max(3, width - len(title) - 1)
    ctx.line(f"{title} {stars}")


def module_ansible(ctx: Context) -> None:
    width = require_tty_width()
    play = f"PLAY [setup {rand_word()}_{rand_word()}]"
    banner(ctx, play, width)
    ctx.line("")
    hosts = [host() for _ in range(random.randint(6, 12))]
    tasks = [
        "TASK [Gathering Facts]",
        f"TASK [{rand_word()}buddy : reload prometheus]",
        f"TASK [{rand_word()}buddy : configure companywiki]",
        f"TASK [{rand_word()}buddy : configure tcp receive window limits]",
        f"TASK [{rand_word()}buddy : copy gitlab-cleanup timer and service]",
        f"TASK [{rand_word()}buddy : restart nginx]",
    ]
    recap: dict[str, list[int]] = {h: [0, 0, 0] for h in hosts}
    for ti, task in enumerate(tasks):
        banner(ctx, task, width)
        for h in hosts:
            if ti == 0 or random.random() < 0.58:
                status, col, idx = "ok", GREEN, 0
            elif random.random() < 0.85:
                status, col, idx = "changed", YELLOW, 1
            else:
                status, col, idx = "failed", RED, 2
            recap[h][idx] += 1
            ctx.line(f"{col}{status}: [{h}]{RESET}")
        ctx.line("")
    banner(ctx, "PLAY RECAP", width)
    for h in hosts:
        ok, changed, failed = recap[h]
        ctx.line(f"{h:<39} : ok={ok:<3} changed={changed:<3} unreachable=0    failed={failed:<3} skipped=0    rescued=0    ignored=0")


