def run(opts: Options) -> None:
    if opts.list_modules:
        write_stdout(list_modules_text())
        return
    if opts.completion_shell:
        write_stdout(COMPLETIONS[opts.completion_shell])
        return
    if opts.print_manpage:
        write_stdout(MANPAGE)
        return

    if opts.inhibit:
        write_stdout("WARN: failed to set up idle inhibition: system: I/O error: No such file or directory (os error 2)\n")

    choices = opts.modules or MODULES[:]
    ctx = Context(opts)
    completed = 0
    target = opts.exit_after_modules
    try:
        while True:
            if target is not None and completed >= target:
                break
            if ctx.deadline is not None and time.monotonic() >= ctx.deadline and completed > 0:
                break
            mod = random.choice(choices)
            MODULE_FUNCS[mod](ctx)
            completed += 1
            if target is None and ctx.deadline is None:
                # Continue forever; a tiny pause prevents a tight loop between short modules.
                ctx.pause(0.05, line=False)
            if target is None and ctx.deadline is not None and time.monotonic() >= ctx.deadline:
                break
    except StopRun:
        pass
    except BrokenPipeError:
        raise SystemExit(1)
    save_and_exit_line()


def main(argv: list[str]) -> int:
    # Let Unix pipelines terminate without a Python traceback.
    try:
        signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    except Exception:
        pass
    for sig in (signal.SIGINT, signal.SIGTERM):
        try:
            signal.signal(sig, signal_handler)
        except Exception:
            pass
    opts = parse_args(argv)
    run(opts)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv))
    except KeyboardInterrupt:
        save_and_exit_line()
        raise SystemExit(0)
